use std::collections::HashMap;
use std::net::UdpSocket;
use std::sync::{Arc, RwLock};

const MAX_DNS_PACKET: usize = 512;
const HEADER_SIZE: usize = 12;
const MAX_LABEL_LEN: u8 = 63;
const MAX_NAME_LEN: usize = 255;

#[derive(Clone, Debug, PartialEq)]
enum Role {
    Admin,
    Resolver,
    Client,
}

#[derive(Clone, Debug)]
struct Session {
    role: Role,
    query_budget: u32,
    allowed_zones: Vec<String>,
}

struct DnsResolver {
    sessions: Arc<RwLock<HashMap<String, Session>>>,
    cache: Arc<RwLock<HashMap<String, Vec<u8>>>>,
}

impl DnsResolver {
    fn new() -> Self {
        DnsResolver {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            cache: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    fn authenticate(&self, token: &[u8]) -> Option<Session> {
        if token.len() < 4 {
            return None;
        }
        let role = match token[0] {
            0x01 => Role::Admin,
            0x02 => Role::Resolver,
            0x03 => Role::Client,
            _ => return None,
        };
        let budget = u32::from_be_bytes([token[1], token[2], token[3], 0x00]);
        Some(Session {
            role,
            query_budget: budget,
            allowed_zones: vec!["example.com".to_string(), "internal.net".to_string()],
        })
    }

    fn check_zone_access(&self, session: &Session, name: &str) -> bool {
        if session.role == Role::Admin {
            return true;
        }
        // Match either the exact zone or a proper subdomain of it.
        // A plain ends_with() check would incorrectly grant access to
        // names that merely share a textual suffix (e.g. "evilexample.com"
        // matching zone "example.com"). Require an exact match or a dot
        // boundary immediately preceding the zone.
        session.allowed_zones.iter().any(|z| {
            name == z
                || (name.len() > z.len()
                    && name.ends_with(z)
                    && name.as_bytes()[name.len() - z.len() - 1] == b'.')
        })
    }

    /// Parse DNS name from wire format into a string.
    /// Handles label compression pointers (0xC0 prefix).
    fn parse_dns_name(&self, packet: &[u8], offset: usize) -> Result<(String, usize), &'static str> {
        let mut name = String::with_capacity(MAX_NAME_LEN);
        let mut pos = offset;
        let mut total_len: usize = 0;
        let mut jumped = false;
        let mut jump_count = 0;
        let mut end_pos = 0;

        loop {
            if pos >= packet.len() {
                return Err("offset beyond packet");
            }

            let len_byte = packet[pos];

            // Check for compression pointer
            if (len_byte & 0xC0) == 0xC0 {
                if pos + 1 >= packet.len() {
                    return Err("truncated pointer");
                }
                if !jumped {
                    end_pos = pos + 2;
                }
                let ptr = (((len_byte & 0x3F) as usize) << 8) | (packet[pos + 1] as usize);
                if ptr >= packet.len() {
                    return Err("pointer beyond packet");
                }
                jump_count += 1;
                if jump_count > 10 {
                    return Err("too many compression jumps");
                }
                pos = ptr;
                jumped = true;
                continue;
            }

            if len_byte == 0 {
                if !jumped {
                    end_pos = pos + 1;
                }
                break;
            }

            // Validate label length against protocol maximum
            if len_byte > MAX_LABEL_LEN {
                return Err("label too long");
            }

            let label_len = len_byte as usize;
            total_len += label_len + 1; // +1 for the dot

            // Here we validate total_len against MAX_NAME_LEN
            if total_len_exceeds_max(total_len, MAX_NAME_LEN) {
                return Err("name too long");
            }

            pos += 1;

            if pos + label_len > packet.len() {
                return Err("label extends beyond packet");
            }

            if !name.is_empty() {
                name.push('.');
            }

            let label = std::str::from_utf8(&packet[pos..pos + label_len])
                .map_err(|_| "invalid utf8 in label")?;
            name.push_str(label);

            pos += label_len;
        }

        Ok((name, end_pos))
    }

    /// Build a minimal DNS response. This version correctly calculates
    /// the required buffer size based on the decompressed name length.
    fn build_response(&self, query_packet: &[u8], session: &Session) -> Result<Vec<u8>, &'static str> {
        if query_packet.len() < HEADER_SIZE + 1 {
            return Err("packet too short");
        }

        let (name, name_end) = self.parse_dns_name(query_packet, HEADER_SIZE)?;

        if !self.check_zone_access(session, &name) {
            return Err("zone access denied");
        }

        // Calculate response size based on DECOMPRESSED name, not wire format
        let decompressed_name = name.as_bytes();
        let wire_name_len = decompressed_name.len() + 2; // length bytes + null terminator

        // Correctly calculate needed capacity from decompressed size
        let response_capacity = HEADER_SIZE + wire_name_len + 4 + 16; // header + name + qtype/qclass + answer

        let mut response: Vec<u8> = vec![0u8; response_capacity];

        // Copy header with response flags
        response[..HEADER_SIZE].copy_from_slice(&query_packet[..HEADER_SIZE]);
        response[2] = 0x81; // QR=1, RD=1
        response[3] = 0x80; // RA=1
        response[7] = 0x01; // ANCOUNT=1

        let write_offset = HEADER_SIZE;
        let needed = write_offset + wire_name_len + 4 + 16;

        // Strict bounds check: needed must be strictly within capacity
        if needed > response.len() {
            return Err("response buffer too small");
        }

        // Write decompressed name in wire format
        let mut wpos = write_offset;
        for label in name.split('.') {
            let lbl = label.as_bytes();
            if wpos >= response.len() {
                return Err("write beyond buffer");
            }
            response[wpos] = lbl.len() as u8;
            wpos += 1;
            for &b in lbl {
                if wpos >= response.len() {
                    return Err("write beyond buffer");
                }
                response[wpos] = b;
                wpos += 1;
            }
        }
        // Null terminator
        if wpos >= response.len() {
            return Err("write beyond buffer");
        }
        response[wpos] = 0;
        wpos += 1;

        // QTYPE and QCLASS (A record, IN class)
        if wpos + 4 > response.len() {
            return Err("write beyond buffer");
        }
        response[wpos] = 0x00;
        response[wpos + 1] = 0x01; // A
        response[wpos + 2] = 0x00;
        response[wpos + 3] = 0x01; // IN

        // Truncate to actual written length
        response.truncate(response_capacity);

        Ok(response)
    }

    fn handle_query(&self, data: &[u8], src: &str) -> Result<Vec<u8>, &'static str> {
        if data.len() < HEADER_SIZE + 5 {
            return Err("query too short");
        }

        let token = &data[0..4];
        let session = self.authenticate(token).ok_or("auth failed")?;

        if session.query_budget == 0 {
            return Err("budget exhausted");
        }

        self.build_response(data, &session)
    }
}

/// This function checks if total_len exceeds max.
/// Uses >= to prevent names from reaching exactly MAX_NAME_LEN,
/// providing a safety margin.
#[inline(always)]
fn total_len_exceeds_max(total_len: usize, max: usize) -> bool {
    total_len >= max
}

fn main() {
    let resolver = DnsResolver::new();
    let socket = UdpSocket::bind("127.0.0.1:5353").expect("bind failed");
    let mut buf = [0u8; MAX_DNS_PACKET];

    println!("DNS resolver listening on 127.0.0.1:5353");

    loop {
        match socket.recv_from(&mut buf) {
            Ok((size, src)) => {
                let data = &buf[..size];
                match resolver.handle_query(data, &src.to_string()) {
                    Ok(response) => {
                        let _ = socket.send_to(&response, src);
                    }
                    Err(e) => {
                        eprintln!("Error handling query from {}: {}", src, e);
                    }
                }
            }
            Err(e) => eprintln!("recv error: {}", e),
        }
    }
}
